/* ================= JENIS SOAL: PILIHAN GANDA, BENAR/SALAH, ISIAN, SUSUN, URUT, PASANGKAN ================= */
const QT={pg:['Pilihan ganda','🔘'],bs:['Benar atau salah','⚖️'],multi:['Pilih semua yang tepat','☑️'],isian:['Ketik jawaban','⌨️'],huruf:['Susun huruf','🔤'],kata:['Susun kata','🧱'],urut:['Urutkan','🔢'],pasang:['Pasangkan','🔗']};
const QT_HELP={multi:'Bisa lebih dari satu pilihan. Tekan Periksa setelah memilih.',isian:'Ketik jawabanmu, lalu tekan Periksa atau Enter.',huruf:'Ketuk huruf sesuai urutan. Ketuk huruf di kotak jawaban untuk mengembalikannya.',kata:'Ketuk kata sesuai urutan untuk menyusun jawaban.',urut:'Pindahkan dengan tombol ▲ ▼ sampai urutannya benar, lalu tekan Periksa.',pasang:'Ketuk kartu soal, lalu ketuk jawaban yang cocok. Ketuk lagi untuk melepas.'};
