function renderAvatarThumbs(){if(!R3D)return false;const cw=canvas.width,ch=canvas.height,S=Math.min(220,cw,ch);if(S<60)return false;
 const P=new Float32Array(16),V=new Float32Array(16),PV=new Float32Array(16);persp(P,30*Math.PI/180,1,.1,50);lookAt(V,[0,1.02,2.7],[0,.64,0]);mul(PV,P,V);
 gl.uniformMatrix4fv(U.uVP,false,PV);gl.uniform3fv(U.uEye,[0,1.02,2.7]);gl.uniform2f(U.uFogR,100,200);gl.uniform1f(U.uWave,0);gl.uniform1f(U.uWf,0);
 setLight('day');gl.enable(gl.SCISSOR_TEST);gl.viewport(0,0,S,S);gl.scissor(0,0,S,S);let ok=0;
 document.querySelectorAll('canvas[data-avc]').forEach(cv=>{const av=avById(cv.dataset.avc);if(!av||!cv.offsetParent)return;gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);mpi=0;curMesh=null;drawAvatar(av,0,0,0,+(cv.dataset.face||.5),0,false,0);const x=cv.getContext('2d');x.clearRect(0,0,cv.width,cv.height);x.drawImage(canvas,0,ch-S,S,S,0,0,cv.width,cv.height);ok++});
 gl.disable(gl.SCISSOR_TEST);gl.viewport(0,0,cw,ch);setLight(LIGHT);return ok>0}
function drawNPC(t){const x=NPC.x,z=NPC.y,dx=rp.x-x,dz=rp.z-z,near=Math.hypot(dx,dz)<3.2;const target=near?Math.atan2(dx,dz):Math.sin(t*.4)*.5;let d=target-npcFace;while(d>Math.PI)d-=Math.PI*2;while(d<-Math.PI)d+=Math.PI*2;npcFace+=d*.08;
 const M0=MT();compose(M0,x,Math.sin(t*1.8)*.02,z,npcFace);const part=(px,py,pz,sx,sy,sz,col,rz=0,em=0)=>{const L=MT();compose(L,px,py,pz,0,0,rz,sx,sy,sz);const W=MT();mul(W,M0,L);draw(MESH.box,W,col,em)};
 part(0,.36,0,.5,.72,.4,COL.robe);part(0,.06,0,.56,.12,.46,COL.robe2);part(0,.6,.205,.14,.3,.02,COL.gold);
 const wave=near?2.3+Math.sin(t*7)*.4:0;part(-.32,.55,0,.13,.42,.15,COL.robe);{const L=MT(),P1=MT(),P2=MT();compose(P1,.32,.74,0,0,0,wave);compose(P2,0,-.2,0,0,0,0,.13,.42,.15);mul(L,P1,P2);const W=MT();mul(W,M0,L);draw(MESH.box,W,COL.robe)}
 part(0,1.0,0,.4,.38,.38,COL.skin);part(0,.86,.12,.36,.2,.18,COL.white);part(0,1.2,0,.42,.08,.4,COL.white);
 part(-.09,1.03,.195,.11,.08,.02,COL.eye);part(.09,1.03,.195,.11,.08,.02,COL.eye);part(0,1.03,.195,.06,.02,.02,COL.eye);
 part(0,1.26,0,.6,.05,.6,COL.eye,0);part(0,1.22,0,.3,.08,.3,COL.eye);part(.26,1.16,.26,.03,.14,.03,COL.gold,0,.6);
 shadow(x,z,.75)}
function drawChest(t){const x=CHEST.x,z=CHEST.y;const M=MT();compose(M,x,.2,z,.3,0,0,.66,.4,.46);draw(MESH.box,M,COL.wood);const B=MT();compose(B,x,.2,z,.3,0,0,.7,.08,.5);draw(MESH.box,B,COL.goldD);
 chestLid+=((chest?1.9:0)-chestLid)*.08;const P1=MT(),P2=MT(),L=MT();compose(P1,x-Math.sin(.3)*.23,.4,z-Math.cos(.3)*.23,.3,-chestLid);compose(P2,0,.08,.23,0,0,0,.7,.16,.48);mul(L,P1,P2);draw(MESH.box,L,COL.woodD);
 const K=MT();compose(K,x+Math.sin(.3)*.24,.36,z+Math.cos(.3)*.24,.3,0,0,.1,.13,.04);draw(MESH.box,K,COL.gold,.5);
 if(chest){const G=MT();compose(G,x,.44+Math.sin(t*3)*.04,z,t,0,0,.22,.32,.22);draw(MESH.gem,G,hex('#7af0ff'),.8)}shadow(x,z,.6)}
function drawPortals(t){const P=palettes[theme]||palettes.cyber,pc=hex(P.portal);missions.forEach((m,i)=>{const sp=SPOTS[i];if(!sp)return;const [x,z]=sp;const M=MT();compose(M,x,.07,z,0,0,0,.86,.14,.86);draw(MESH.cyl,M,COL.stone);const M2=MT();compose(M2,x,.16,z,0,0,0,.66,.06,.66);draw(MESH.cyl,M2,COL.stoneD);
 if(completed[i]){const G=MT();compose(G,x,.55+Math.sin(t*2+i)*.06,z,t*1.5+i,0,0,.32,.42,.32);draw(MESH.gem,G,COL.leaf,.55);return}
 const ry=Math.sin(t*.6+i)*.5,bob=Math.sin(t*1.5+i)*.04;const R=MT();compose(R,x,.78+bob,z,ry,0,0,1.02,1.18,1);draw(MESH.torus,R,pc,.75);
 for(let k=0;k<3;k++){const a=t*1.8+k*2.094+i;const O=MT();compose(O,x+Math.cos(a)*.62,.8+Math.sin(a*1.3)*.25,z+Math.sin(a)*.62,a*2,0,0,.13,.2,.13);draw(MESH.gem,O,pc,.9)}})}
function drawPortalGlows(t){const P=palettes[theme]||palettes.cyber,pc=hex(P.portal);missions.forEach((m,i)=>{if(completed[i]||!SPOTS[i])return;const [x,z]=SPOTS[i];const ry=Math.sin(t*.6+i)*.5,bob=Math.sin(t*1.5+i)*.04,pulse=1+Math.sin(t*3+i)*.05;const D=MT();compose(D,x,.78+bob,z,ry,Math.PI/2,0,.9*pulse,.02,1.08*pulse);draw(MESH.disc,D,pc,1,.42);const G=MT();compose(G,x,.2,z,0,0,0,1.15,.02,1.15);draw(MESH.disc,G,pc,1,.18+Math.sin(t*2+i)*.06)})}
function drawCoins(t){coinSpots.forEach((p,i)=>{if(collected.has(i))return;const [x,z]=p;const M=MT();compose(M,x,.45+Math.sin(t*3+i)*.07,z,t*2.4+i,Math.PI/2,0,.36,.07,.36);draw(MESH.cyl,M,COL.gold,.3);const N=MT();compose(N,x,.45+Math.sin(t*3+i)*.07,z,t*2.4+i,Math.PI/2,0,.2,.09,.2);draw(MESH.cyl,N,COL.goldD,.2)})}
function drawClouds(t){for(let i=0;i<8;i++){const base=hash(i,3)*40-6,x=((base+t*.25*(.6+hash(i,9)*.6))%52)-14,z=-12-hash(i,5)*14,y=3.5+hash(i,7)*3;for(let k=0;k<3;k++){const M=MT();const s=.9+k*.25-(k===2?.5:0);compose(M,x+k*.7-.7,y+(k===1?.25:0),z,0,0,0,s*1.4,s*.9,s*1.1);draw(MESH.ico,M,COL.white,.55)}}}
function drawParticles(dt){parts=parts.filter(p=>(p.life-=dt)>0);for(const p of parts){p.vy-=6*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;if(p.y<.05){p.y=.05;p.vy*=-.4}const s=p.size*Math.min(1,p.life*2);const M=MT();compose(M,p.x,p.y,p.z,p.life*8,p.life*5,0,s,s*1.3,s);draw(MESH.gem,M,p.col,.85)}}
function burst(x,y,z,col,n=14,sp=2.4){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,u=Math.random()*sp;parts.push({x,y,z,vx:Math.cos(a)*u,vy:2+Math.random()*3,vz:Math.sin(a)*u,life:.7+Math.random()*.6,size:.08+Math.random()*.08,col})}}
function drawHighlight(t){const tg=currentTarget();if(!tg)return;const M=MT();const s=1+Math.sin(t*5)*.06;compose(M,tg.x,.03,tg.y,0,Math.PI/2,0,1.25*s,1.25*s,1.25*s);draw(MESH.torus,M,hex('#ffffff'),1,.85)}
const labelBox=$('labels');let LBL={};
function rebuildLabels(){labelBox.innerHTML='';floaters=[];LBL={you:mkLbl('Kamu','you'),npc:mkLbl('Prof. Byte','npc'),portals:missions.map((m,i)=>mkLbl(String(i+1),'portal'))};if(typeof PEERS!=='undefined')PEERS.forEach(q=>q.lbl=mkLbl(q.n,'peer'))}
function mkLbl(text,cls){const d=document.createElement('div');d.className='lbl '+cls;d.textContent=text;labelBox.appendChild(d);return d}
function place(el,x,y,z){const p=project(x,y,z);if(!p||p.x<-60||p.y<-60||p.x>viewW+60||p.y>viewH+60){el.style.display='none';return}el.style.display='';el.style.transform=`translate(${p.x.toFixed(1)}px,${p.y.toFixed(1)}px) translate(-50%,-100%)`}
function updateLabels(){if(!LBL.you)return;placePeerLabels();place(LBL.you,rp.x,1.62+hAt(rp.x,rp.z),rp.z);place(LBL.npc,NPC.x,1.75,NPC.y);const tg=currentTarget();LBL.npc.classList.toggle('near',!!tg&&tg.kind==='npc');LBL.npc.textContent=tg&&tg.kind==='npc'?'💬 Prof. Byte':'Prof. Byte';
 LBL.portals.forEach((el,i)=>{const sp=SPOTS[i];if(!sp){el.style.display='none';return}const [x,z]=sp;el.classList.toggle('done',!!completed[i]);el.textContent=completed[i]?'✓':String(i+1);el.classList.toggle('near',!!tg&&tg.kind==='portal'&&tg.i===i);place(el,x,completed[i]?1.15:1.62,z)});
 floaters=floaters.filter(f=>{f.t+=1/60;if(f.t>1.2){f.el.remove();return false}const p=project(f.x,1.3+f.t*1.1,f.z);if(p){f.el.style.transform=`translate(${p.x}px,${p.y}px) translate(-50%,-100%)`;f.el.style.opacity=String(Math.min(1,(1.2-f.t)*3))}return true})}
function floatText(x,z,text,color='#ffc83d'){if(!R3D)return;const el=document.createElement('div');el.className='floater';el.textContent=text;el.style.color=color;labelBox.appendChild(el);floaters.push({el,x,z,t:0})}

/* ================= GERAK & INTERAKSI ================= */
const DIRS={up:[0,-1,Math.PI],down:[0,1,0],left:[-1,0,-Math.PI/2],right:[1,0,Math.PI/2]};
const MODALS=['quizModal','npcModal','winModal','stuModal','worldModal','pinModal','askModal'];
const modalOpen=()=>MODALS.some(id=>$(id).classList.contains('show'));
function currentTarget(){const cand=[];missions.forEach((m,i)=>{if(completed[i]||!SPOTS[i])return;const [x,y]=SPOTS[i];if(adj(player,{x,y}))cand.push({kind:'portal',i,x,y})});if(adj(player,NPC))cand.push({kind:'npc',x:NPC.x,y:NPC.y});if(!chest&&adj(player,CHEST))cand.push({kind:'chest',x:CHEST.x,y:CHEST.y});if(!cand.length)return null;const fx_=Math.round(Math.sin(rp.face)),fz=Math.round(Math.cos(rp.face));return cand.find(c=>c.x===player.x+fx_&&c.y===player.y+fz)||cand[0]}
function interactWith(tg){if(!tg)return false;faceTo(tg.x,tg.y);if(tg.kind==='portal')openQuiz(tg.i);else if(tg.kind==='npc')talk();else if(tg.kind==='chest')openChest();return true}
function faceTo(x,y){const dx=x-player.x,dy=y-player.y;if(dx||dy)rp.targetFace=Math.atan2(dx,dy)}
function canPlay(){if(!gameReady())return false;if(askName&&!student.name&&!nameSkipped){openStudent();return false}return true}
function tryMove(dir){if(modalOpen()||anim||!gameReady())return false;const [dx,dy,face]=DIRS[dir];rp.targetFace=face;const nx=player.x+dx,ny=player.y+dy;
 const pi=portalAt(nx,ny);if(pi>=0){heldDir=null;path=[];openQuiz(pi);return false}
 if(nx===NPC.x&&ny===NPC.y){heldDir=null;path=[];talk();return false}
 if(!chest&&nx===CHEST.x&&ny===CHEST.y){heldDir=null;path=[];openChest();return false}
 if(blocked(nx,ny)){if(T-lastBump>.3){SFX.bump();lastBump=T}return false}
 if(!startedAt)startedAt=Date.now();
 anim={fx:player.x,fz:player.y,tx:nx,tz:ny,t:0};player={x:nx,y:ny};steps++;if(!R3D)arrive();return true}
function arrive(){anim=null;rp.x=player.x;rp.z=player.y;const c=coinSpots.findIndex((p,i)=>!collected.has(i)&&p[0]===player.x&&p[1]===player.y);if(c>=0){collected.add(c);coins++;addXP(10);SFX.coin();burst(player.x,.5,player.y,COL.gold,12);floatText(player.x,player.y,'+10 XP');if(collected.size===coinSpots.length)toast('🪙 Semua koin terkumpul!','gold')}
 if(!path.length&&pendingTarget){const tg=pendingTarget;pendingTarget=null;const now=currentTarget();if(now&&now.kind===tg.kind&&now.i===tg.i)interactWith(now);else if(adj(player,tg))interactWith(tg)}
 renderAll();save()}
function openChest(){if(chest)return;chest=true;addXP(50);SFX.chest();burst(CHEST.x,.6,CHEST.y,COL.gold,22,2.8);floatText(CHEST.x,CHEST.y,'+50 XP');toast('💎 Peti harta terbuka! +50 XP','gold');renderAll();save()}
function interact(){if(modalOpen())return;const tg=currentTarget();if(tg){interactWith(tg);return}$('gameHint').textContent='Tidak ada objek di dekatmu. Dekati portal, peti, atau Professor Byte.';SFX.bump()}
function walkTo(tg){if(!gameReady())return;path=[];pendingTarget=null;let goals;if(tg.kind){if(adj(player,tg)){interactWith(tg);return}goals=goalsAround(tg.x,tg.y);pendingTarget=tg}else goals=[[tg.x,tg.y]];const p=findPath(goals);if(!p){pendingTarget=null;toast('Jalan ke sana tertutup.');return}path=p}
function stepPath(){if(anim||!path.length||modalOpen())return;const n=path.shift();const dx=n.x-player.x,dy=n.y-player.y;const dir=dx===1?'right':dx===-1?'left':dy===1?'down':'up';if(Math.abs(dx)+Math.abs(dy)!==1||!tryMove(dir)){path=[];pendingTarget=null}}
function tapAt(cx,cy){if(modalOpen())return;const ents=[];missions.forEach((m,i)=>{if(!completed[i]&&SPOTS[i]){const [x,y]=SPOTS[i];ents.push({kind:'portal',i,x,y,h:.8})}});ents.push({kind:'npc',x:NPC.x,y:NPC.y,h:.9});if(!chest)ents.push({kind:'chest',x:CHEST.x,y:CHEST.y,h:.3});let best=null,bd=40;for(const e of ents){const p=project(e.x,e.h,e.y);if(!p)continue;const d=Math.hypot(p.x-cx,p.y-cy);if(d<bd){bd=d;best=e}}if(best){walkTo(best);return}
 const nx=cx/viewW*2-1,ny=1-cy/viewH*2;const un=z=>{const v=[IVP[0]*nx+IVP[4]*ny+IVP[8]*z+IVP[12],IVP[1]*nx+IVP[5]*ny+IVP[9]*z+IVP[13],IVP[2]*nx+IVP[6]*ny+IVP[10]*z+IVP[14],IVP[3]*nx+IVP[7]*ny+IVP[11]*z+IVP[15]];return[v[0]/v[3],v[1]/v[3],v[2]/v[3]]};const a=un(-1),b=un(1);if(Math.abs(b[1]-a[1])<1e-6)return;const k=-a[1]/(b[1]-a[1]);if(k<0)return;const x=Math.round(a[0]+(b[0]-a[0])*k),y=Math.round(a[2]+(b[2]-a[2])*k);if(x<0||y<0||x>=COLS||y>=ROWS)return;
 const pi=portalAt(x,y);if(pi>=0){walkTo({kind:'portal',i:pi,x,y});return}if(x===NPC.x&&y===NPC.y){walkTo({kind:'npc',x,y});return}if(!chest&&x===CHEST.x&&y===CHEST.y){walkTo({kind:'chest',x,y});return}if(blocked(x,y))return;walkTo({x,y})}

