function loadScript(src){return new Promise((res,rej)=>{if(document.querySelector(`script[data-src="${src}"]`)){res();return}const s=document.createElement('script');s.src=src;s.dataset.src=src;s.onload=res;s.onerror=()=>{s.remove();rej(new Error('cdn'))};document.head.appendChild(s)})}
async function pdfjsDoc(u8){if(!window.pdfjsLib)await loadScript(PDFJS+'pdf.min.js');pdfjsLib.GlobalWorkerOptions.workerSrc=PDFJS+'pdf.worker.min.js';return pdfjsLib.getDocument({data:u8.slice()}).promise}
async function pdfjsText(doc,status){let out='';for(let p=1;p<=doc.numPages;p++){status('Membaca PDF halaman '+p+' dari '+doc.numPages+'...');const pg=await doc.getPage(p);const tc=await pg.getTextContent();let lastY=null;for(const it of tc.items){const y=it.transform?it.transform[5]:null;if(lastY!==null&&y!==null&&Math.abs(y-lastY)>2)out+='\n';out+=it.str;if(it.hasEOL)out+='\n';lastY=y}out+='\n\n'}return out}
