async function pdfOcr(doc,status){const n=Math.min(doc.numPages,20),blobs=[];for(let p=1;p<=n;p++){status('Menyiapkan halaman '+p+' untuk OCR...');const pg=await doc.getPage(p);const vp=pg.getViewport({scale:2});const c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await pg.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;blobs.push(await new Promise(r=>c.toBlob(r,'image/png')))}return ocrBlobs(blobs,status)}
