 const distract=(ans,n,avoid)=>{const al=ans.toLowerCase(),isProp=/^[A-Z]/.test(ans),kd=kind(al);const pool=kws.filter(k=>k.l!==al&&!al.includes(k.l)&&!k.l.includes(al)&&!(avoid&&wordRe(k.l).test(avoid)));const same=pool.filter(k=>kind(k.l)===kd||(kd==='frasa'&&kind(k.l)==='benda'));const near=shuffle(same.filter(k=>Math.abs(k.l.length-al.length)<=5).slice(0,14));const rest=shuffle(same.filter(k=>!near.includes(k)).slice(0,14));const other=kd==='frasa'?[]:shuffle(pool.filter(k=>!same.includes(k)).slice(0,10));return[...near,...rest,...other].slice(0,n).map(k=>isProp?cap(k.f):k.f)};
 const maxC=kws.length?kws[0].c:1,defSet=new Set(defs.map(d=>d.term.toLowerCase()));
 const bestKw=(present,skip)=>{let best=null,bw=-99;for(const k of present){if(skip&&k===skip)continue;const w=(defSet.has(k.l)?5:0)+Math.min(k.c,4)-(k.c>=maxC*.6&&kws.length>12?4:0)+(k.l.length>=6?1:0)+(kind(k.l)==='benda'?1:0)+Math.random()*.5;if(w>bw){bw=w;best=k}}return best};
 const mk=(type,q,ans,ds,ex,skill)=>{const opts=shuffle([ans,...ds]);return{type,title:'',q,a:opts,c:opts.indexOf(ans),ex:ex.length>240?ex.slice(0,237)+'…':ex,skill,src:'auto'}};
 const used=new Set(),pools={def:[],cloze:[],truth:[],num:[],rev:[]};
 const defTerms=defs.map(d=>d.term);
