 for(const s of sents){if(s.length>230)continue;const present=kws.filter(k=>wordRe(k.l).test(s));if(!present.length)continue;const k=bestKw(present);const m=s.match(wordRe(k.l));const form=m[2];const ds=distract(form,3,s);if(ds.length<2)continue;const ans=form;const dsf=ds.map(x=>/^[A-Z]/.test(form)?cap(x):x.toLowerCase());const blank=s.replace(wordRe(k.l),(a,p1)=>p1+'________');pools.cloze.push({s,q:mk('cloze','Lengkapi kalimat berikut sesuai materi:\n\n"'+blank+'"',ans,dsf,s,'Memahami '+k.f.toLowerCase())})}
