const GAS_CODE=`/** EDUPLAY: server misi + dunia per kelas + penerima hasil siswa (versi 6) */

// 1) GANTI kunci di bawah dengan kata sandi Anda sendiri. Jangan dibagikan ke siswa.
var KUNCI_GURU = 'GANTI_DENGAN_KUNCI_RAHASIA';

var REKAP = ${JSON.stringify(REKAP_HEAD)};
var DETAIL = ${JSON.stringify(DETAIL_HEAD)};
var KOLOM_MISI = ${JSON.stringify(TPL_HEAD)};
var KOLOM_DUNIA = ['Dunia'].concat(KOLOM_MISI);
var MAKS = 50;

function doGet(e) {
  var p = (e && e.parameter) || {};
  if (p.a === 'misi') return json_(misiUntukSiswa_());
  if (p.a === 'versi') return json_({ ok: true, v: 6 });
  if (p.a === 'dunia') return json_(duniaUntukSiswa_(String(p.id || '')));
  if (p.a === 'daftar') return json_(daftarDunia_());
  if (p.d) return catatLink_(p.d);
  return halaman_('✓ EDUPLAY siap menerima hasil (versi 6).');
}

function doPost(e) {
  var data = JSON.parse((e && e.postData && e.postData.contents) || '{}');
  if (data.a === 'posisi') return json_(posisi_(data));
  if (data.a === 'simpanMisi') return json_(kunci_(data.kunci, function () { return simpanMisi_(data.cfg); }));
  if (data.a === 'ambilMisi') return json_(kunci_(data.kunci, function () { return { ok: true, cfg: bacaMisi_() }; }));
  if (data.a === 'simpanDunia') return json_(kunci_(data.kunci, function () { return simpanDunia_(data.id, data.missions); }));
  if (data.a === 'hapusDunia') return json_(kunci_(data.kunci, function () { return simpanDunia_(data.id, null); }));
  return catat_(function (ss) {
    if (sudahAda_(ss, data.rekap[data.rekap.length - 1])) return 'sudah';
    tulis_(ss, 'Rekap', REKAP, [data.rekap]);
    if (data.detail && data.detail.length) tulis_(ss, 'Detail', DETAIL, data.detail);
    return 'ok';
  }, false);
}

// ---------- Posisi pemain: siswa di dunia yang sama saling melihat ----------
function posisi_(d) {
  var w = String(d.w || '').slice(0, 60), id = String(d.id || '').slice(0, 40);
  if (!w || !id) return { ok: false, error: 'Data posisi tidak lengkap.' };
  var cache = CacheService.getScriptCache(), key = 'ruang_' + Utilities.base64EncodeWebSafe(w).slice(0, 200), now = Date.now(), room = {};
  var lock = LockService.getScriptLock();
  if (lock.tryLock(4000)) {
    try {
      room = JSON.parse(cache.get(key) || '{}');
      var lama = room[id] || {}, e = String(d.e || '').slice(0, 4);
      room[id] = { n: String(d.n || 'Teman').slice(0, 18), av: String(d.av || '').slice(0, 300), x: d.x | 0, y: d.y | 0, s: d.s | 0, e: e || lama.e || '', et: e ? now : (lama.et || 0), t: now };
      Object.keys(room).forEach(function (k) { if (now - room[k].t > 20000) delete room[k]; });
      var ids = Object.keys(room);
      if (ids.length > 60) ids.sort(function (a, b) { return room[a].t - room[b].t; }).slice(0, ids.length - 60).forEach(function (k) { delete room[k]; });
      cache.put(key, JSON.stringify(room), 120);
    } finally { lock.releaseLock(); }
  } else room = JSON.parse(cache.get(key) || '{}');
  var out = [];
  Object.keys(room).forEach(function (k) {
    if (k === id) return;
    var r = room[k];
    out.push({ id: k, n: r.n, av: r.av, x: r.x, y: r.y, s: r.s, e: r.e, ea: r.et ? now - r.et : 99999 });
  });
  return { ok: true, p: out };
}

// ---------- Misi ----------
function kunci_(k, fn) {
  if (!KUNCI_GURU || /^GANTI_DENGAN/.test(KUNCI_GURU)) return { ok: false, error: 'KUNCI_GURU di kode Apps Script belum diganti.' };
  if (String(k || '') !== KUNCI_GURU) { Utilities.sleep(1500); return { ok: false, error: 'Kunci guru salah.' }; }
  var lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try { return fn(); } catch (err) { return { ok: false, error: String(err) }; } finally { lock.releaseLock(); }
}

function simpanMisi_(cfg) {
  if (!cfg || !cfg.missions || cfg.missions.length < 15) return { ok: false, error: 'Minimal 15 misi.' };
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName('Misi') || ss.insertSheet('Misi');
  sh.clear();
  var rows = [KOLOM_MISI];
  cfg.missions.slice(0, MAKS).forEach(function (m, i) {
    rows.push([i + 1].concat(keBaris_(m)));
  });
  var rg = sh.getRange(1, 1, rows.length, KOLOM_MISI.length);
  rg.setNumberFormat('@');
  rg.setValues(rows.map(function (r) { return r.map(teks_); }));
  sh.getRange(1, 1, 1, KOLOM_MISI.length).setFontWeight('bold').setBackground('#6b4ce6').setFontColor('#ffffff');
  sh.setFrozenRows(1);
  var meta = { subject: cfg.subject, topic: cfg.topic, grade: cfg.grade, genre: cfg.genre, theme: cfg.theme, worldTitle: cfg.worldTitle,
    askName: cfg.askName !== false, teacher: cfg.teacher || null,
    made: Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyy-MM-dd HH:mm') };
  PropertiesService.getScriptProperties().setProperty('META', JSON.stringify(meta));
  var c = bacaMisi_();
  return { ok: true, id: c.id, jumlah: c.missions.length, made: meta.made };
}

function bacaMisi_() {
  var sh = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Misi');
  var meta = JSON.parse(PropertiesService.getScriptProperties().getProperty('META') || '{}');
  var missions = [];
  if (sh && sh.getLastRow() > 1) {
    sh.getRange(2, 1, sh.getLastRow() - 1, KOLOM_MISI.length).getDisplayValues().forEach(function (r) {
      if (!String(r[2]).trim()) return;
      var m = dariBaris_(r.slice(1));
      if (!m.title) m.title = 'Misi ' + (missions.length + 1);
      m.src = 'server';
      missions.push(m);
    });
  }
  var cfg = { missions: missions.slice(0, MAKS), subject: meta.subject || '', topic: meta.topic || '', grade: meta.grade || '',
    genre: meta.genre || '', theme: meta.theme || 'cyber', worldTitle: meta.worldTitle || 'Algorithm Island',
    askName: meta.askName !== false, teacher: meta.teacher || null, made: meta.made || '' };
  var dig = Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, JSON.stringify(cfg));
  cfg.id = 'S' + dig.map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join('').slice(0, 12);
  return cfg;
}

function misiUntukSiswa_() {
  var c = bacaMisi_();
  if (c.missions.length < 15) return { ok: false, error: 'Guru belum menerbitkan minimal 15 misi.' };
  return { ok: true, id: c.id, z: pack_(c, c.id) };
}

// ---------- Jenis soal: satu baris sheet <-> satu misi ----------
var JENIS = { pg: 'Pilihan ganda', bs: 'Benar/Salah', multi: 'Pilih semua yang tepat', isian: 'Isian', huruf: 'Susun huruf', kata: 'Susun kata', urut: 'Urutkan', pasang: 'Pasangkan' };
function kodeJenis_(s) {
  s = String(s || '').toLowerCase().trim();
  if (!s) return 'pg';
  if (JENIS[s]) return s;
  if (/semua|jamak|kompleks|multi/.test(s)) return 'multi';
  if (/benar|salah|true|false/.test(s)) return 'bs';
  if (/isian|ketik|singkat/.test(s)) return 'isian';
  if (/huruf|anagram/.test(s)) return 'huruf';
  if (/kata|kalimat/.test(s)) return 'kata';
  if (/urut/.test(s)) return 'urut';
  if (/pasang|jodoh|cocok/.test(s)) return 'pasang';
  return 'pg';
}
function keBaris_(m) {
  var t = JENIS[m.t] ? m.t : 'pg', a = t === 'bs' ? [] : (m.a || []), kunci = '';
  if (t === 'pg') kunci = 'ABCD'.charAt(m.c || 0);
  else if (t === 'bs') kunci = (m.c | 0) ? 'Salah' : 'Benar';
  else if (t === 'multi') kunci = (m.k || []).map(function (i) { return 'ABCD'.charAt(i); }).join(',');
  return [m.title, m.q, a[0], a[1], a[2], a[3], kunci, m.ex, m.skill, JENIS[t]];
}
function dariBaris_(r) {
  var t = kodeJenis_(r[9]), a = [r[2], r[3], r[4], r[5]], kv = String(r[6] || '').trim(), m = { title: r[0], q: r[1], ex: r[7], skill: r[8], c: 0 };
  if (t === 'pg' || t === 'multi') { while (a.length > 3 && !String(a[a.length - 1]).trim()) a.pop(); }
  else a = a.filter(function (x) { return String(x).trim(); });
  m.a = a;
  if (t === 'pg') { var c = 'ABCD'.indexOf(kv.toUpperCase().charAt(0)); m.c = c < 0 ? 0 : c; }
  else if (t === 'bs') { m.a = ['Benar', 'Salah']; m.c = /^(s|f|x|0|tidak)/i.test(kv) ? 1 : 0; }
  else if (t === 'multi') { m.k = (kv.toUpperCase().match(/[A-D]/g) || ['A']).map(function (h) { return 'ABCD'.indexOf(h); }); m.c = m.k[0]; }
  if (t !== 'pg') m.t = t;
  return m;
}

// ---------- Misi per dunia (paket perangkat ajar) ----------
function idDunia_(id) { return /^[a-z0-9-]{2,24}$/.test(String(id || '')); }

function bacaSemuaDunia_() {
  var sh = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Dunia'), out = {};
  if (!sh || sh.getLastRow() < 2) return out;
  sh.getRange(2, 1, sh.getLastRow() - 1, KOLOM_DUNIA.length).getDisplayValues().forEach(function (r) {
    var id = String(r[0]).trim();
    if (!id || !String(r[3]).trim()) return;
    var m = dariBaris_(r.slice(2));
    if (!m.title) m.title = 'Misi';
    (out[id] = out[id] || []).push(m);
  });
  return out;
}

function sidik_(obj) {
  var dig = Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, JSON.stringify(obj));
  return 'W' + dig.map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join('').slice(0, 12);
}

function simpanDunia_(id, missions) {
  if (!idDunia_(id)) return { ok: false, error: 'Kode dunia tidak valid.' };
  if (missions && (missions.length < 15 || missions.length > MAKS)) return { ok: false, error: 'Satu dunia berisi 15 sampai ' + MAKS + ' misi.' };
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName('Dunia') || ss.insertSheet('Dunia');
  var lama = sh.getLastRow() > 1 ? sh.getRange(2, 1, sh.getLastRow() - 1, KOLOM_DUNIA.length).getValues().filter(function (r) { return String(r[0]) !== id; }) : [];
  var baru = (missions || []).map(function (m, i) {
    return [id, i + 1].concat(keBaris_(m));
  });
  var rows = [KOLOM_DUNIA].concat(lama, baru);
  sh.clear();
  var rg = sh.getRange(1, 1, rows.length, KOLOM_DUNIA.length);
  rg.setNumberFormat('@');
  rg.setValues(rows.map(function (r) { return r.map(teks_); }));
  sh.getRange(1, 1, 1, KOLOM_DUNIA.length).setFontWeight('bold').setBackground('#6b4ce6').setFontColor('#ffffff');
  sh.setFrozenRows(1);
  return { ok: true, id: id, jumlah: baru.length, made: Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyy-MM-dd HH:mm') };
}

function duniaUntukSiswa_(id) {
  if (!idDunia_(id)) return { ok: false, error: 'Kode dunia tidak valid.' };
  var m = bacaSemuaDunia_()[id];
  if (!m || m.length < 15) return { ok: true, kosong: true };
  var obj = { missions: m.slice(0, MAKS) }, h = sidik_(obj);
  return { ok: true, id: h, n: obj.missions.length, z: pack_(obj, h) };
}

function daftarDunia_() {
  var all = bacaSemuaDunia_(), out = {};
  Object.keys(all).forEach(function (id) { if (all[id].length >= 15) out[id] = { n: Math.min(MAKS, all[id].length), h: sidik_({ missions: all[id].slice(0, MAKS) }) }; });
  return { ok: true, v: 6, dunia: out };
}

function pack_(obj, id) {
  var b = Utilities.newBlob(JSON.stringify(obj)).getBytes(), k = Utilities.newBlob('EV' + id).getBytes();
  for (var i = 0; i < b.length; i++) {
    var v = (b[i] & 255) ^ (k[i % k.length] & 255) ^ ((i * 31 + 7) & 255);
    b[i] = v > 127 ? v - 256 : v;
  }
  return Utilities.base64Encode(b);
}

function teks_(v) {
  v = (v === null || v === undefined) ? '' : String(v);
  return /^[=+\\-@]/.test(v) ? "'" + v : v;
}

// ---------- Hasil siswa ----------
function catatLink_(raw) {
  return catat_(function (ss) {
    var d = JSON.parse(raw), r = d.r, id = r[r.length - 1];
    if (sudahAda_(ss, id)) return 'Hasil ' + r[1] + ' sudah tercatat sebelumnya. Tab ini boleh ditutup.';
    tulis_(ss, 'Rekap', REKAP, [r]);
    var w = String(d.w || '').split('.'), rows = [];
    for (var i = 0; i < w.length && w[i] !== ''; i++) {
      var n = Number(w[i]) || 0;
      rows.push([r[0], r[1], r[2], i + 1, '', (d.s && d.s[i]) || '', '', '', n, n === 0 ? 'Ya' : 'Tidak', id]);
    }
    if (rows.length) tulis_(ss, 'Detail', DETAIL, rows);
    return '✓ Hasil ' + r[1] + ' (nilai ' + r[11] + ') sudah tercatat. Tab ini boleh ditutup.';
  }, true);
}

function catat_(fn, html) {
  var lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    var msg = fn(SpreadsheetApp.getActiveSpreadsheet());
    return html ? halaman_(msg) : json_({ ok: true, status: msg });
  } catch (err) {
    return html ? halaman_('Gagal mencatat: ' + err) : json_({ ok: false, error: String(err) });
  } finally {
    lock.releaseLock();
  }
}

function tulis_(ss, nama, header, rows) {
  var sh = ss.getSheetByName(nama) || ss.insertSheet(nama);
  if (sh.getLastRow() === 0) {
    sh.appendRow(header);
    sh.getRange(1, 1, 1, header.length).setFontWeight('bold').setBackground('#6b4ce6').setFontColor('#ffffff');
    sh.setFrozenRows(1);
  }
  sh.getRange(sh.getLastRow() + 1, 1, rows.length, header.length).setValues(rows.map(function (r) { return r.map(teks_); }));
}

function sudahAda_(ss, id) {
  var sh = ss.getSheetByName('Rekap');
  if (!sh || sh.getLastRow() < 2) return false;
  var v = sh.getRange(2, REKAP.length, sh.getLastRow() - 1, 1).getDisplayValues();
  for (var i = 0; i < v.length; i++) if (String(v[i][0]) === String(id)) return true;
  return false;
}

function json_(o) {
  return ContentService.createTextOutput(JSON.stringify(o)).setMimeType(ContentService.MimeType.JSON);
}

function halaman_(msg) {
  var t = String(msg).replace(/&/g, '&amp;').replace(/</g, '&lt;');
  return HtmlService.createHtmlOutput('<meta name="viewport" content="width=device-width,initial-scale=1"><div style="font-family:sans-serif;padding:40px 20px;text-align:center;font-size:20px;line-height:1.5">' + t + '</div>').setTitle('EDUPLAY');
}`;
