function hashPin(pin,salt){const d=new TextEncoder().encode('eduverse|'+salt+'|'+pin);let h1=0x811c9dc5,h2=0x9747b28c,h3=0x2545f491;for(let r=0;r<3000;r++)for(let i=0;i<d.length;i++){const x=d[i]^(r&255);h1=Math.imul(h1^x,16777619)>>>0;h2=Math.imul(h2^(x+i),2246822519)>>>0;h3=Math.imul(h3^h1,3266489917)>>>0}return[h1,h2,h3].map(v=>v.toString(16).padStart(8,'0')).join('')}
function randChars(n,abc='ABCDEFGHJKLMNPQRSTUVWXYZ23456789'){const b=new Uint8Array(n);(window.crypto||{}).getRandomValues?crypto.getRandomValues(b):b.forEach((_,i)=>b[i]=Math.random()*256);return[...b].map(x=>abc[x%abc.length]).join('')}
