function myLastRecord(){if(lastRecord)return lastRecord;const n=(student.name||'').toLowerCase();for(let i=history.length-1;i>=0;i--)if(n&&history[i].name.toLowerCase()===n)return history[i];return null}

/* ================= DIALOG KONFIRMASI (pengganti confirm/prompt) ================= */
let askResolve=null,askNeed='';
function confirmBox(text,{ok='Ya, lanjutkan',title='Konfirmasi',danger=false,need=''}={}){return new Promise(res=>{if(askResolve)askResolve(false);askResolve=res;askNeed=need;$('askTitle').textContent=title;$('askText').textContent=text;$('askYes').textContent=ok;$('askYes').className=danger?'danger':'primary';$('askInputRow').hidden=!need;$('askInput').value='';$('askInputLabel').textContent=need?'Ketik '+need+' untuk melanjutkan':'';$('askWarn').textContent='';$('askModal').classList.add('show');setTimeout(()=>(need?$('askInput'):$('askYes')).focus(),60)})}
function askDone(v){if(v&&askNeed&&$('askInput').value.trim().toUpperCase()!==askNeed){$('askWarn').textContent='Ketik '+askNeed+' dengan benar.';return}$('askModal').classList.remove('show');const r=askResolve;askResolve=null;if(r)r(v)}
$('askYes').addEventListener('click',()=>askDone(true));$('askNo').addEventListener('click',()=>askDone(false));
$('askInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();askDone(true)}});
$('askModal').addEventListener('click',e=>{if(e.target.id==='askModal')askDone(false)});

