function reportText(r){return['EDUPLAY · Laporan belajar','Nama: '+r.name+(r.absen?' (No. '+r.absen+')':''),'Kelas: '+(r.kelas||'-'),'Mapel/Topik: '+[r.subject,r.topic].filter(Boolean).join(' / '),'Nilai: '+r.score+' ('+r.first+' dari '+r.n+' benar di percobaan pertama)','Akurasi: '+r.acc+'%','Waktu bermain: '+fmtDur(r.duration),'Selesai: '+fmtTime(r.time),'Rincian (no:salah): '+r.details.map(d=>d.no+':'+d.wrongs).join(' '),'ID hasil: '+r.id].join('\n')}
async function copyReport(r){if(!r)return;const t=reportText(r);try{await navigator.clipboard.writeText(t);toast('📋 Laporan disalin. Tempel di WhatsApp atau Classroom untuk guru.','green')}catch(e){await confirmBox(t,{title:'Salin laporan ini',ok:'Tutup'})}}
function renderMyReport(){const r=myLastRecord();$('myReportRow').hidden=!r;if(!r)return;$('myReport').hidden=ONLINE&&!DL;const a=$('mySendLink');a.hidden=!(ONLINE&&sheetUrl);if(!a.hidden){a.href=sheetLink(r);a.onclick=()=>{r.sent=true;saveHistory()}}}

/* ================= LINK ONLINE (pemilik & terbit) ================= */
const DRAFT_KEY='eduverse-draft-'+(CFG.id||'base');
function saveDraft(){try{localStorage.setItem(DRAFT_KEY,JSON.stringify({...publishable(),mode,autoCount,library}))}catch(e){}renderPubStatus()}
function pubSnapshot(){return EMBED?JSON.stringify({missions:CFG.missions,subject:CFG.subject,topic:CFG.topic,grade:CFG.grade,genre:CFG.genre,theme:CFG.theme,worldTitle:CFG.worldTitle,sheetUrl:CFG.sheetUrl||'',askName:CFG.askName!==false}):''}
function isDirty(){return JSON.stringify(publishable())!==pubSnapshot()}
function renderPubStatus(){if(!(ONLINE&&OWNER))return;const el=$('pubStatus');if(!el)return;if(!EMBED)setSendLine(el,'Belum pernah diterbitkan. Siswa yang membuka link sekarang mendapat soal bawaan.','busy');else if(isDirty())setSendLine(el,'Ada perubahan yang belum diterbitkan. Siswa masih memainkan versi '+(CFG.made||'sebelumnya')+'.','busy');else setSendLine(el,'✓ Link sudah memakai versi terbaru ('+(CFG.made||'')+', '+(CFG.missions||[]).length+' misi).','ok')}
function restoreDraft(){let d=null;try{d=JSON.parse(localStorage.getItem(DRAFT_KEY)||'null')}catch(e){}if(!d||!Array.isArray(d.missions)||!d.missions.length)return;if(EMBED&&JSON.stringify({missions:d.missions,subject:d.subject,topic:d.topic,grade:d.grade,genre:d.genre,theme:d.theme,worldTitle:d.worldTitle,sheetUrl:d.sheetUrl||'',askName:d.askName!==false})===pubSnapshot())return;
 missions=d.missions.slice(0,MAXM).map(fixMission);['subject','topic','grade','genre'].forEach(k=>{if(d[k]!==undefined)setField(k,d[k])});if(palettes[d.theme])theme=d.theme;if(d.worldTitle)worldTitle=d.worldTitle;sheetUrl=d.sheetUrl||'';askName=d.askName!==false;if(d.mode)mode=d.mode;if(d.autoCount)autoCount=+d.autoCount;if(Array.isArray(d.library))library=d.library;
 normalize();if(R3D)buildWorld();snapPlayer();rebuildLabels();renderWorldHeader();renderAll();checkReady();$('sheetUrl').value=sheetUrl;$('askName').checked=askName;setMode(mode);renderLibrary();toast('Draf yang belum diterbitkan dipulihkan','purple')}
async function publishOnline(){if(!(ONLINE&&OWNER))return;if(!gameReady()){toast('Lengkapi minimal 15 misi dulu.');renderReady();return}if(!pinData){openPin('setup',null);toast('Buat PIN guru dulu.');return}
 if(!(await confirmBox('Terbitkan '+missions.length+' misi ke link ini? Siswa yang membuka link akan langsung mendapat dunia ini. Progres siswa di versi lama dimulai dari awal.',{title:'Terbitkan ke link',ok:'🌐 Terbitkan'})))return;
 let art=null;try{art=await claude.use('artifact')}catch(e){}if(!art){setSendLine($('pubStatus'),'Penerbitan tidak tersedia di tampilan ini. Buka link di claude.ai sebagai pemilik, lalu coba lagi.','err');return}
 const cfg=makeCfg(),html=docWithConfig(packCfg(cfg));try{localStorage.setItem('eduverse-draft-'+cfg.id,JSON.stringify({...publishable(),mode,autoCount,library}))}catch(e){}
 setSendLine($('pubStatus'),'Menerbitkan...','busy');$('publishBtn').disabled=true;
 try{await art.publish(html);try{localStorage.removeItem(DRAFT_KEY)}catch(e){}setSendLine($('pubStatus'),'✓ Terbit. Halaman dimuat ulang dengan versi baru.','ok')}
 catch(e){const c=e&&e.code;setSendLine($('pubStatus'),c==='conflict'?'Ada versi lain yang baru saja diterbitkan. Halaman akan dimuat ulang; periksa lalu terbitkan lagi.':c==='not_granted'||c==='not_writer'?'Hanya pemilik atau editor link yang bisa menerbitkan.':'Gagal menerbitkan ('+(c||e&&e.message||'galat')+'). Coba lagi.','err')}
 $('publishBtn').disabled=false}
let onlineReady=false;
async function initOnline(){if(onlineReady)return;onlineReady=true;
 claude.use('downloads').then(d=>{DL=d||null;renderMyReport();['winExcel','exportHistory'].forEach(id=>{if($(id))$(id).hidden=!DL})}).catch(()=>{DL=null});
 let own=false;try{const u=await claude.use('user');if(u){own=!!(await Promise.resolve(u.isOwner&&u.isOwner()));if(!own&&u.canEdit)own=!!(await Promise.resolve(u.canEdit()))}}catch(e){own=false}
 OWNER=own;refreshPin();if(OWNER){restoreDraft();renderEditorSelect();toast('👩‍🏫 Kamu pemilik link ini. Teacher Studio tersedia (pakai PIN).','purple')}
 applyAccess();checkReady();renderStuChip()}

/* paket tema: 36 dunia, 582 misi (JSON 222111 B, deflate 67085 B) */
const THEME_Z='';

/* ================= PAKET TEMA DARI PERANGKAT AJAR ================= */
const PK_SUBJ={Informatika:'Informatika',KKA:'Koding dan Kecerdasan Artifisial'};
let THEMES=null,themesLoading=null,pkMapel='Semua',pkKelas='Semua';const pkPicked=new Set();
function loadThemes(){if(THEMES)return Promise.resolve(THEMES);if(!themesLoading)themesLoading=(async()=>{try{const bin=Uint8Array.from(atob(THEME_Z),c=>c.charCodeAt(0));THEMES=JSON.parse(new TextDecoder().decode(await inflate(bin,'deflate-raw')))}catch(e){console.warn(e);THEMES=[]}return THEMES})();return themesLoading}
function themeById(id){return(THEMES||[]).find(t=>t.id===id)}
function worldStory(){const T=(THEMES||[]).find(t=>t.dunia===worldTitle);if(T)return T.cerita;const tp=$('topic').value.trim();return tp&&worldTitle!=='Algorithm Island'?'Selamat datang di '+worldTitle+'! Buka setiap portal, jawab tantangannya, dan kuasai materi '+tp+'.':''}
function pkLevel(k){return LEVELS[gradeLevel('Kelas '+k)]}
function pkSky(t){const P=palettes[t.tema]||palettes.cyber;return skyFor(P,pkLevel(t.kelas).time)}
async function renderPaket(){const grid=$('pkGrid');if(!grid||isStudent())return;if(!THEMES){grid.innerHTML='<p class="small muted">Memuat paket tema...</p>';await loadThemes()}
 if(!THEMES.length){grid.innerHTML='<p class="small">Paket tema tidak bisa dibuka di browser ini. Perbarui browser (Chrome, Edge, atau Safari versi terbaru), lalu muat ulang halaman.</p>';return}
 document.querySelectorAll('[data-pk-mapel]').forEach(b=>b.classList.toggle('on',b.dataset.pkMapel===pkMapel));document.querySelectorAll('[data-pk-kelas]').forEach(b=>b.classList.toggle('on',b.dataset.pkKelas===pkKelas));
 const list=THEMES.filter(t=>(pkMapel==='Semua'||t.mapel===pkMapel)&&(pkKelas==='Semua'||t.kelas===pkKelas));
 $('pkCount').textContent=list.length+' dunia · '+list.reduce((a,t)=>a+t.missions.length,0)+' misi';
 grid.innerHTML=list.map(t=>{const P=palettes[t.tema]||palettes.cyber,L=pkLevel(t.kelas),[sT,sB]=pkSky(t),on=pkPicked.has(t.id),ms=teacherWorldMissions(t.id),o=OV[t.id],ed=curWorld===t.id;
  return`<article class="pkcard${on?' picked':''}${ed?' editing':''}" data-pk="${t.id}">
  <div class="pkband" style="background:linear-gradient(180deg,${sT},${sB} 70%,${P.ground} 70%,${P.ground2})"><span class="pkemo">${P.emoji}</span><span class="pklv">${L.icon} ${L.name}</span>${ed?'<span class="pkedit">Sedang diatur</span>':''}</div>
  <div class="pkbody"><p class="pkbab">${escapeHTML(t.mapel)} · Kelas ${t.kelas} · Bab ${t.bab}</p><h4>${escapeHTML(t.dunia)}</h4><p class="pkjudul">${escapeHTML(t.judul)}</p>${o&&o.m?`<p class="pkcustom">✎ Disesuaikan guru · ${o.m.length} misi${o.dirty?' · belum diterbitkan':''}</p>`:o&&o.dirty?'<p class="pkcustom">↺ Kembali ke soal bawaan · belum diterbitkan</p>':''}
  <details class="pksoal"><summary>Lihat ${ms.length} soal</summary><ol>${ms.map(m=>`<li><span class="pkqt">${QT[qType(m)][1]}</span> ${escapeHTML(String(m.q).replace(/\n→ /,' → '))} <b>${escapeHTML(keyText(m))}</b></li>`).join('')}</ol></details>
  <div class="pkact"><button class="primary" data-pk-use="${t.id}">${ed?'Sedang diatur':'Atur misi'}</button><button data-pk-xl="${t.id}" title="Unduh soal dunia ini sebagai Excel">Excel</button><label class="pkchk"><input type="checkbox" data-pk-sel="${t.id}"${on?' checked':''}> Gabung</label></div></div></article>`}).join('');
 renderPkBar();renderPkPub()}
function renderPkPub(){const d=dirtyWorlds(),row=$('pkPubRow');row.hidden=!d.length;if(d.length)$('pkPubText').textContent=d.length+' dunia sudah diubah tetapi belum diterbitkan ke link siswa.'}
function renderPkBar(){const n=pkPicked.size,bar=$('pkBar');bar.hidden=!n;if(!n)return;$('pkMerge').textContent=n>1?'Gabungkan jadi dunia guru':'Jadikan dunia guru';const tot=[...pkPicked].reduce((a,id)=>a+teacherWorldMissions(id).length,0);$('pkSel').textContent=n+' bab dipilih · '+tot+' soal'+(tot>MAXM?' (diambil '+MAXM+' soal merata dari tiap bab)':'');$('pkMerge').disabled=n<1}
function pkApply(o,msg){$('subject').value=o.subject;ensureGradeOption(o.grade);$('grade').value=o.grade;$('topic').value=o.topic;theme=palettes[o.tema]?o.tema:'cyber';$('theme').value=theme;worldTitle=o.dunia;if(R3D)buildWorld();
 startNewWorld(o.missions.map(m=>({...m,src:'paket'})),msg);setView('play');if(R3D)setupCamera(-1);toast((palettes[theme]||palettes.cyber).emoji+' '+worldTitle+' siap dengan '+missions.length+' misi','purple')}
function setField(k,v){if(k==='grade')ensureGradeOption(v);$(k).value=v}
function ensureGradeOption(g){if(!g)return;const sel=$('grade');if(![...sel.options].some(o=>o.value===g||o.text===g)){const o=document.createElement('option');o.textContent=g;sel.appendChild(o)}}
async function usePaket(id){await loadThemes();const t=themeById(id);if(!t)return;
 if(missions.some(m=>m.q.trim())&&!(await confirmBox('Ganti '+missions.length+' misi yang ada sekarang dengan '+t.missions.length+' misi dunia "'+t.dunia+'"? Kemajuan main di perangkat ini ikut diulang.',{ok:'Pakai dunia ini',title:'Pakai paket tema'})))return;
 pkApply({subject:PK_SUBJ[t.mapel]||t.mapel,grade:'SMA Kelas '+t.kelas,topic:'Bab '+t.bab+' · '+t.judul,tema:t.tema,dunia:t.dunia,missions:t.missions},
  t.missions.length+' misi dari perangkat ajar '+t.mapel+' Kelas '+t.kelas+' Bab '+t.bab+' dimuat. Periksa atau sunting di Mission Editor, lalu tekan "Terbitkan misi ke link siswa" agar siswa mendapat dunia ini.')}
function spread(arr,k){if(k>=arr.length)return arr.slice();const out=[];for(let i=0;i<k;i++)out.push(arr[Math.floor((i+.5)*arr.length/k)]);return out}
async function mergePaket(){await loadThemes();const ts=[...pkPicked].map(themeById).filter(Boolean).sort((a,b)=>THEMES.indexOf(a)-THEMES.indexOf(b));if(!ts.length)return;const MS=ts.map(t=>teacherWorldMissions(t.id));
 const tot=MS.reduce((a,m)=>a+m.length,0),cap=Math.min(MAXM,tot);let q=MS.map(m=>Math.max(1,Math.floor(cap*m.length/tot)));let left=cap-q.reduce((a,b)=>a+b,0);for(let i=0;left>0;i=(i+1)%ts.length)if(q[i]<MS[i].length){q[i]++;left--}
 const list=ts.flatMap((t,i)=>spread(MS[i],q[i]).map(m=>({...m,title:m.title})));
 const mapels=[...new Set(ts.map(t=>t.mapel))],kelas=[...new Set(ts.map(t=>t.kelas))],babs=ts.map(t=>(mapels.length>1?t.mapel+' ':'')+t.bab);
 if(!(await confirmBox('Jadikan '+list.length+' misi dari '+ts.length+' bab sebagai dunia guru? Dunia guru yang lama diganti. Dunia guru muncul paling atas di pilihan dunia siswa yang tingkat kelasnya sama.',{ok:'Jadikan dunia guru',title:'Dunia guru'})))return;if(curWorld&&!(await applyWorld('')))return;
 pkApply({subject:mapels.map(m=>PK_SUBJ[m]||m).join(' & '),grade:'SMA Kelas '+kelas[kelas.length-1],topic:'Gabungan Bab '+babs.join(', '),tema:ts[0].tema,dunia:(ts.length>1?'Tantangan ':'Tugas ')+ts[0].dunia,missions:list},
  list.length+' misi dari '+ts.length+' bab ('+babs.join(', ')+') menjadi dunia guru'+(ts.length>1?', diambil merata dari setiap bab':'')+'. Periksa di Mission Editor, lalu terbitkan dunia guru ke link siswa.');
 pkPicked.clear();renderPkBar()}
async function pkExcel(id){await loadThemes();const t=themeById(id);if(!t)return;const rows=[TPL_HEAD,...teacherWorldMissions(id).map(rowOf)];
 const ok=await download(makeXlsx([{name:'Misi',rows,widths:[5,18,48,24,24,24,24,14,42,28]}]),'Misi_'+slug(t.mapel+'_Kelas_'+t.kelas+'_Bab_'+t.bab+'_'+t.dunia)+'.xlsx');if(ok)toast('💾 Soal '+t.dunia+' diunduh','green')}
function renderThemeOptions(){const sel=$('theme'),cur=sel.value;sel.innerHTML='<option value="auto">Otomatis sesuai mapel</option>'+Object.entries(palettes).map(([k,P])=>`<option value="${k}">${P.emoji} ${escapeHTML(P.name)}</option>`).join('');sel.value=palettes[cur]||cur==='auto'?cur:'auto'}
function bindPaket(){const g=$('pkGrid');if(!g)return;
 document.querySelectorAll('[data-pk-mapel]').forEach(b=>b.addEventListener('click',()=>{pkMapel=b.dataset.pkMapel;renderPaket()}));
 document.querySelectorAll('[data-pk-kelas]').forEach(b=>b.addEventListener('click',()=>{pkKelas=b.dataset.pkKelas;renderPaket()}));
 g.addEventListener('click',e=>{const u=e.target.closest('[data-pk-use]'),x=e.target.closest('[data-pk-xl]');if(u)editWorld(u.dataset.pkUse);else if(x)pkExcel(x.dataset.pkXl)});
 g.addEventListener('change',e=>{const c=e.target.closest('[data-pk-sel]');if(!c)return;const id=c.dataset.pkSel;if(c.checked)pkPicked.add(id);else pkPicked.delete(id);c.closest('.pkcard').classList.toggle('picked',c.checked);renderPkBar()});
 $('pkMerge').addEventListener('click',mergePaket);$('pkPubAll').addEventListener('click',async()=>{const d=dirtyWorlds();if(d.length&&(await confirmBox('Terbitkan '+d.length+' dunia yang sudah diubah ke link siswa?',{ok:'🌐 Terbitkan',title:'Terbitkan dunia'})))await publishWorlds(d)});$('pkClear').addEventListener('click',()=>{pkPicked.clear();renderPaket()})}

/* ================= DUNIA PER KELAS: SISWA MEMILIH, GURU MENGATUR MISI ================= */
const KELAS_LIST=['X-1','X-2','X-3','XI-A1','XI-1','XI-2','XI-3','XI-4','XII-A1','XII-1','XII-2','XII-3'];
function kelasTingkat(k){const m=String(k||'').trim().toUpperCase().match(/^(XII|XI|X)(?![A-Z])/);return m?m[1]:''}
function fillKelas(sel,val){val=String(val||'').trim();const list=KELAS_LIST.slice();if(val&&!list.includes(val))list.push(val);sel.innerHTML='<option value="">Pilih kelas</option>'+list.map(k=>`<option>${escapeHTML(k)}</option>`).join('');sel.value=val}

/* --- penyimpanan --- */
const lsGet=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k)||'null');return v==null?d:v}catch(e){return d}};
const lsSet=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){return false}};
let OV=lsGet(OV_KEY,{})||{},WC=lsGet(WCACHE_KEY,{})||{},lastOvSig='';
const mJSON=list=>JSON.stringify((list||[]).map(m=>[m.title,m.q,m.a,+m.c,m.ex||'',m.skill||'',m.t||'',m.k||0]));
const plainM=list=>(list||[]).map(m=>{const o={title:m.title,q:m.q,a:m.a.slice(),c:+m.c,ex:m.ex||'',skill:m.skill||''};if(m.t&&m.t!=='pg')o.t=m.t;if(m.t==='multi')o.k=(m.k||[]).slice();return o});
function saveOV(){if(!lsSet(OV_KEY,OV))toast('Penyimpanan perangkat penuh. Unduh Excel sebagai cadangan.')}
const DM_CACHE={};
function defaultMissions(id,n){const t=themeById(id);if(!t)return[];n=Math.max(MINM,Math.min(MAXM,n||t.missions.length));const k=id+':'+n;return DM_CACHE[k]||(DM_CACHE[k]=remixWorld(t.missions,n,id))}
function teacherWorldMissions(id){const o=OV[id];return o&&o.m?o.m:defaultMissions(id)}
let SRVN=null;
async function loadSrvList(){if(!SERVER)return;try{const r=await fetchT(SERVER_URL+'?a=daftar&t='+Date.now(),8000);const j=await r.json();if(j&&j.ok&&j.dunia){SRVN=j.dunia;let ch=false;for(const id of Object.keys(WC))if(!SRVN[id]){delete WC[id];ch=true}if(ch)lsSet(WCACHE_KEY,WC)}}catch(e){}}
function worldCount(id){if(!isStudent()){const o=OV[id];if(o&&o.m)return o.m.length}else{if(SRVN&&SRVN[id])return SRVN[id].n;if(WC[id])return WC[id].m.length;if(CFG.worlds&&Array.isArray(CFG.worlds[id]))return CFG.worlds[id].length}return defaultMissions(id).length}

/* --- kemajuan per dunia --- */
function snapProgress(){return{n:missions.length,completed:completed.slice(),wrongs:wrongs.slice(),xp,coins,right,wrong,steps,player:{...player},collected:[...collected],chest,startedAt,finishedAt,finished}}
function readProg(id){return(lsGet(PROG_KEY,{})||{})[id||'guru']||null}
function setProgress(p){if(!p||p.n!==missions.length)p={};completed=Array.isArray(p.completed)?p.completed:[];wrongs=Array.isArray(p.wrongs)?p.wrongs:[];xp=+p.xp||0;coins=+p.coins||0;right=+p.right||0;wrong=+p.wrong||0;steps=+p.steps||0;player=p.player?{...p.player}:{...START};collected=new Set(p.collected||[]);chest=!!p.chest;startedAt=+p.startedAt||0;finishedAt=+p.finishedAt||0;finished=!!p.finished}
function saveWorldState(){const P=lsGet(PROG_KEY,{})||{};P[curWorld||'guru']=snapProgress();lsSet(PROG_KEY,P);
 if(!isStudent()&&curWorld&&THEMES){const sig=mJSON(missions);if(sig===lastOvSig)return;lastOvSig=sig;const cur=OV[curWorld];
  let ch=false;if(sig===mJSON(defaultMissions(curWorld))){if(cur&&cur.m){OV[curWorld]={m:null,dirty:true};ch=true}}else{OV[curWorld]={m:plainM(missions),dirty:true};ch=true}if(ch){saveOV();renderWorldCtx();if(mode==='paket')renderPaket()}}}

/* --- dunia milik guru (dunia yang ditugaskan) --- */
function ownWorld(){if(!curWorld)return{missions,subject:$('subject').value,topic:$('topic').value,grade:$('grade').value,genre:$('genre').value,theme,worldTitle};return lsGet(OWN_KEY,null)}
function stashOwn(){lsSet(OWN_KEY,{missions:plainM(missions),subject:$('subject').value,topic:$('topic').value,grade:$('grade').value,genre:$('genre').value,theme,worldTitle})}
function restoreOwn(){const o=lsGet(OWN_KEY,null);if(o&&Array.isArray(o.missions)&&o.missions.length){missions=o.missions.slice(0,MAXM).map(fixMission);['subject','topic','grade','genre'].forEach(k=>{if(o[k]!==undefined)setField(k,o[k])});theme=palettes[o.theme]?o.theme:'cyber';worldTitle=o.worldTitle||'Algorithm Island'}else{missions=clone(packs.Informatika);theme='cyber';worldTitle='Algorithm Island'}}
function exportWorlds(){const out={};Object.keys(OV).forEach(id=>{if(OV[id]&&OV[id].m)out[id]=OV[id].m});return out}

/* --- misi dunia untuk siswa: server guru → file siswa → bawaan --- */
async function studentWorldMissions(id){
 if(SERVER){try{const r=await fetchT(SERVER_URL+'?a=dunia&id='+encodeURIComponent(id)+'&t='+Date.now(),9000);const j=await r.json();
   if(j&&j.ok){if(j.kosong)delete WC[id];else{const c=unpackCfg(JSON.stringify({id:j.id,z:j.z}));if(c&&Array.isArray(c.missions)&&c.missions.length>=MINM)WC[id]={m:c.missions,h:j.id}}lsSet(WCACHE_KEY,WC)}}catch(e){}
  if(WC[id])return WC[id].m}
 if(CFG.worlds&&Array.isArray(CFG.worlds[id])&&CFG.worlds[id].length>=MINM)return CFG.worlds[id];
 return defaultMissions(id)}

/* --- pindah dunia --- */
let switching=false;
function worldTingkat(){if(curWorld){const t=themeById(curWorld);return t?t.kelas:''}const l=gradeLevel(isStudent()?CFG.grade:$('grade').value);return l===1?'X':l===2?'XI':l===3?'XII':''}
async function applyWorld(id,{startup=false}={}){if(switching)return false;switching=true;try{
 id=id||'';let T=null;if(id){await loadThemes();T=themeById(id);if(!T){if(startup){curWorld='';worldReady=true}toast('Dunia tidak ditemukan.');return false}}
 if(!startup&&worldReady){saveWorldState();if(!curWorld&&!isStudent())stashOwn()}
 worldReady=false;const list=id?(isStudent()?await studentWorldMissions(id):teacherWorldMissions(id)):null;
 curWorld=id;picked=true;try{localStorage.setItem(PICK_KEY,id)}catch(e){}
 if(T){missions=list.slice(0,MAXM).map(m=>fixMission({...m,src:'paket'}));setField('subject',PK_SUBJ[T.mapel]||T.mapel);setField('grade','SMA Kelas '+T.kelas);setField('topic','Bab '+T.bab+' · '+T.judul);theme=palettes[T.tema]?T.tema:'cyber';worldTitle=T.dunia;lastOvSig=mJSON(missions)}
 else if(isStudent()){if(CFG.missions&&CFG.missions.length)applyConfig(CFG);else missions=[]}
 else restoreOwn();
 setProgress(readProg(id));normalize();chestLid=chest?1:0;shown.xp=null;shown.coins=null;activeMission=-1;worldReady=true;
 if(R3D)buildWorld();snapPlayer();rebuildLabels();renderWorldHeader();renderAll();if(!isStudent()){renderEditorSelect();if(mode==='paket')renderPaket()}checkReady();renderWorldCtx();save();if(R3D)setupCamera(-1);return true}
 finally{switching=false}}

/* --- pilihan dunia di layar siswa --- */
function teacherWorldFor(t){if(!(CFG.missions&&CFG.missions.length>=MINM))return false;const g=gradeLevel(CFG.grade);return !g||g===gradeLevel('Kelas '+t)}
function lastScore(title){for(let i=history.length-1;i>=0;i--)if(history[i].world===title)return history[i].score;return null}
function wCard(id,o){const P=palettes[o.tema]||palettes.cyber,L=LEVELS[gradeLevel('Kelas '+o.kelas)]||LEVELS[0],[sT,sB]=skyFor(P,L.time),pr=readProg(id),n=pr&&pr.n||o.n,done=pr&&Array.isArray(pr.completed)?pr.completed.filter(Boolean).length:0,cur=picked&&curWorld===id,sc=pr&&pr.finished?lastScore(o.title):null;
 const st=pr&&pr.finished?'✓ Selesai'+(sc!=null?' · nilai '+sc:''):done?done+' dari '+n+' misi':n+' misi · belum dimulai';
 return`<button class="wcard${cur?' cur':''}${pr&&pr.finished?' fin':''}" data-world="${id}"><span class="wband" style="background:linear-gradient(180deg,${sT},${sB} 68%,${P.ground} 68%,${P.ground2})"><span class="pkemo">${P.emoji}</span>${cur?'<span class="pklv">Sedang dimainkan</span>':''}</span><span class="wbody"><span class="pkbab">${escapeHTML(o.bab)}</span><b>${escapeHTML(o.title)}</b><span class="pkjudul">${escapeHTML(o.sub)}</span><span class="wstat">${st}</span><span class="wbar"><i style="width:${Math.round(done/Math.max(1,n)*100)}%"></i></span></span></button>`}
async function openPicker(){if(!isStudent())return;if(!student.name&&!nameSkipped){openStudent();return}await loadThemes();fillKelas($('wKelas'),student.kelas);renderPicker();$('worldModal').classList.add('show');if(SERVER)loadSrvList().then(()=>{if($('worldModal').classList.contains('show'))renderPicker()});setTimeout(()=>{const c=document.querySelector('.wcard.cur')||document.querySelector('.wcard');if(c)c.focus({preventScroll:true})},80)}
function renderPicker(){const k=$('wKelas').value,t=kelasTingkat(k),box=$('wList');$('worldTier').textContent=t?'Tingkat '+t:'Pilih kelasmu';$('wClose').hidden=!(picked&&gameReady());
 if(!t){box.innerHTML='<p class="wempty">Pilih kelasmu dulu. Dunia yang muncul disesuaikan dengan tingkatan kelasmu.</p>';return}
 let html='';if(teacherWorldFor(t))html+='<h3 class="wgrp">Dari guru</h3><div class="wgrid">'+wCard('',{tema:CFG.theme,kelas:t,title:CFG.worldTitle||'Dunia guru',sub:CFG.topic||CFG.subject||'',bab:CFG.subject||'Ditugaskan guru',n:CFG.missions.length})+'</div>';
 for(const mp of ['Informatika','KKA']){const ws=(THEMES||[]).filter(x=>x.kelas===t&&x.mapel===mp);if(!ws.length)continue;html+=`<h3 class="wgrp">${escapeHTML(PK_SUBJ[mp]||mp)}</h3><div class="wgrid">`+ws.map(x=>wCard(x.id,{tema:x.tema,kelas:x.kelas,title:x.dunia,sub:x.judul,bab:'Bab '+x.bab,n:worldCount(x.id)})).join('')+'</div>'}
 box.innerHTML=html||'<p class="wempty">Belum ada dunia untuk tingkat ini.</p>'}
async function pickWorld(id){const same=picked&&curWorld===id&&gameReady();$('worldModal').classList.remove('show');if(currentView!=='play')setView('play');
 if(!same){toast('Memuat dunia...','purple');const ok=await applyWorld(id);if(!ok)return;toast((palettes[theme]||palettes.cyber).emoji+' Selamat datang di '+worldTitle+'!','green')}
 if(finished&&(await confirmBox('Kamu sudah menyelesaikan '+worldTitle+'. Main lagi dari awal? Nilai lama tetap tersimpan di riwayat.',{ok:'Main lagi',title:'Dunia sudah selesai'})))resetGame();
 canvas.focus({preventScroll:true})}
function needPicker(){if(!isStudent())return false;const t=kelasTingkat(student.kelas);if(!picked)return true;if(!t)return false;const w=worldTingkat();return !!w&&w!==t}

/* --- guru: konteks dunia yang sedang diatur --- */
function renderWorldCtx(){const el=$('worldCtx');if(!el||isStudent())return;$('srvPublish').textContent=curWorld?'🌐 Terbitkan dunia ini ke link siswa':'🌐 Terbitkan dunia guru ke link siswa';$('srvPull').textContent=curWorld?'📥 Ambil dunia ini dari spreadsheet':'📥 Ambil misi dari spreadsheet';
 if(!curWorld){el.innerHTML='<b>Sedang mengatur: dunia guru</b><span>Dunia ini muncul paling atas di pilihan dunia siswa yang tingkat kelasnya sama. Untuk mengatur misi dunia perangkat ajar, buka <b>📚 Paket perangkat ajar</b> lalu pilih <b>Atur misi</b>.</span>';el.className='worldctx';return}
 const T=themeById(curWorld),o=OV[curWorld],P=palettes[theme]||palettes.cyber;if(!T)return;
 const st=o&&o.m?(o.dirty?'disesuaikan, belum diterbitkan':'disesuaikan dan sudah diterbitkan'):o&&o.dirty?'kembali ke soal bawaan, belum diterbitkan':'soal bawaan';
 el.className='worldctx pk';el.innerHTML=`<b>${P.emoji} Sedang mengatur: ${escapeHTML(T.dunia)}</b><span>${escapeHTML(T.mapel)} Kelas ${T.kelas} · Bab ${T.bab} · ${missions.length} misi (${st}). Ubah, tambah, atau hapus misi di Mission Editor, maksimal ${MAXM} misi. Siswa kelas ${T.kelas} memilih dunia ini sendiri.</span><span class="wccount"><label for="wcN">Jumlah misi</label><select id="wcN">${Array.from({length:MAXM-MINM+1},(_,k)=>k+MINM).map(n=>`<option${n===missions.length?' selected':''}>${n}</option>`).join('')}${missions.length<MINM||missions.length>MAXM?`<option selected>${missions.length}</option>`:''}</select><button id="wcGen">✦ Susun ulang misi</button><small>Soal bab ini diolah menjadi beragam jenis: pilihan ganda, benar/salah, isian, susun huruf atau kata, pilih semua, dan pasangkan.</small></span><span class="wcact"><button id="wcReset"${o&&o.m?'':' disabled'}>↺ Kembalikan soal bawaan</button><button id="wcOwn">Kembali ke dunia guru</button></span>`;
 $('wcReset').onclick=resetWorldMissions;$('wcGen').onclick=regenWorld;$('wcOwn').onclick=()=>applyWorld('')}
async function resetWorldMissions(){if(!curWorld)return;if(!(await confirmBox('Kembalikan '+worldTitle+' ke '+defaultMissions(curWorld).length+' soal bawaan perangkat ajar? Misi yang Anda ubah atau tambahkan di dunia ini terhapus.',{ok:'Kembalikan',danger:true,title:'Soal bawaan'})))return;
 startNewWorld(defaultMissions(curWorld).map(m=>({...m,src:'paket'})),'Dunia dikembalikan ke soal bawaan. Terbitkan lagi agar siswa ikut mendapat soal bawaan.');renderWorldCtx()}
async function regenWorld(){if(!curWorld)return;const n=+$('wcN').value||MINM,T=themeById(curWorld);if(!T)return;const edited=OV[curWorld]&&OV[curWorld].m;if(edited&&!(await confirmBox('Susun ulang '+worldTitle+' menjadi '+n+' misi dari soal bab ini? Perubahan manual Anda di dunia ini diganti.',{ok:'Susun ulang',title:'Jumlah misi'})))return;
 startNewWorld(defaultMissions(curWorld,n).map(m=>({...m,src:'paket'})),n+' misi disusun dari '+T.missions.length+' soal Bab '+T.bab+' dengan jenis soal yang beragam. Periksa di Mission Editor, lalu terbitkan dunia ini.');renderWorldCtx();toast('✦ '+n+' misi siap','purple')}
async function editWorld(id){if(curWorld===id){$('editMission').scrollIntoView({behavior:'smooth',block:'center'});return}const ok=await applyWorld(id);if(!ok)return;const t=themeById(id);$('studioMessage').textContent='Mengatur misi '+t.dunia+' ('+t.mapel+' Kelas '+t.kelas+' Bab '+t.bab+'). Sunting, tambah, atau hapus misi di Mission Editor (maksimal '+MAXM+'), lalu terbitkan dunia ini ke link siswa.';toast((palettes[theme]||palettes.cyber).emoji+' Mengatur '+t.dunia,'purple');$('worldCtx').scrollIntoView({behavior:'smooth',block:'start'})}

/* --- guru: terbitkan misi per dunia ke Apps Script versi 6 --- */
async function srvVersion(){try{const r=await fetchT(sheetUrl+'?a=versi&t='+Date.now(),15000);const j=await r.json();return +j.v||0}catch(e){return 0}}
function dirtyWorlds(){return Object.keys(OV).filter(id=>OV[id]&&OV[id].dirty)}
async function publishWorlds(ids){if(ONLINE)return;const line=$('srvStatus');
 if(!saveSheetUrl()||!sheetUrl||!scriptId()){setSendLine(line,'Isi URL Apps Script yang benar (berakhiran /exec) di kolom Google Sheets dulu.','err');line.scrollIntoView({behavior:'smooth',block:'center'});return}
 if(!pinData){openPin('setup',null);toast('Buat PIN guru dulu.');return}
 const kunci=getTKey();if(!kunci){setSendLine(line,'Isi kunci guru (KUNCI_GURU di Apps Script).','err');$('teacherKey').focus();return}
 if(curWorld)saveWorldState();
 for(const id of ids){const o=OV[id];if(o&&o.m&&(o.m.length<MINM||!o.m.map(fixMission).every(missionValid))){const t=themeById(id);setSendLine(line,(t?t.dunia:id)+' belum siap: butuh minimal '+MINM+' misi yang lengkap.','err');return}}
 setSendLine(line,'Memeriksa versi Apps Script...','busy');const v=await srvVersion();
 if(v<5){setSendLine(line,v>=4?V5_MSG:'Apps Script di spreadsheet masih versi lama. Salin kode versi 6 di atas, tempel menggantikan semua kode lama, ganti KUNCI_GURU, simpan, lalu Terapkan → Kelola deployment → ✏️ Edit → Versi baru → Terapkan.','err');return}
 let n=0;$('srvPublish').disabled=true;
 try{for(const id of ids){const o=OV[id],t=themeById(id);setSendLine(line,'Menerbitkan '+(t?t.dunia:id)+' ('+(n+1)+' dari '+ids.length+')...','busy');
   if(o&&o.m)await srvPost({a:'simpanDunia',kunci,id,missions:o.m});else await srvPost({a:'hapusDunia',kunci,id});
   if(OV[id]){OV[id].dirty=false;if(!OV[id].m)delete OV[id]}saveOV();n++}
  setSendLine(line,'✓ '+n+' dunia terbit. Siswa yang memilih dunia itu langsung mendapat misi terbaru.','ok');toast('🌐 '+n+' dunia terbit','green')}
 catch(e){const m=String(e.message||e);setSendLine(line,(n?n+' dunia sudah terbit. ':'')+(m.includes('Failed to fetch')||e.name==='AbortError'?'Tidak bisa menghubungi Apps Script. Periksa internet dan URL-nya.':m.includes('salah')?m+' Isi kolom ini harus sama persis dengan KUNCI_GURU di Apps Script.':m),'err')}
 $('srvPublish').disabled=false;renderWorldCtx();if(mode==='paket')renderPaket()}
async function publishCurrentWorld(){if(!curWorld)return;saveWorldState();const o=OV[curWorld];if(!gameReady()){toast('Lengkapi minimal '+MINM+' misi dulu.');renderReady();return}
 if(!(await confirmBox('Terbitkan '+missions.length+' misi '+worldTitle+' ke link siswa?'+(o&&o.m?'':' Dunia ini memakai soal bawaan, jadi siswa mendapat soal bawaan.'),{title:'Terbitkan dunia',ok:'🌐 Terbitkan'})))return;
 if(!OV[curWorld])OV[curWorld]={m:null,dirty:true};else OV[curWorld].dirty=true;await publishWorlds([curWorld])}
async function pullWorld(id){if(!saveSheetUrl()||!scriptId()){setSendLine($('srvStatus'),'Isi URL Apps Script dulu.','err');return}setSendLine($('srvStatus'),'Mengambil dunia dari spreadsheet...','busy');
 try{const r=await fetchT(sheetUrl+'?a=dunia&id='+encodeURIComponent(id)+'&t='+Date.now(),20000);let j;try{j=await r.json()}catch(e){throw new Error('Apps Script masih versi lama. Perbarui ke versi 6.')}if(!j.ok)throw new Error(j.error||'Gagal');
  if(j.kosong){setSendLine($('srvStatus'),'Spreadsheet belum punya misi khusus untuk dunia ini. Siswa memakai soal bawaan.','ok');return}
  const c=unpackCfg(JSON.stringify({id:j.id,z:j.z}));if(!(await confirmBox('Ganti misi '+worldTitle+' dengan '+c.missions.length+' misi dari spreadsheet?',{ok:'Ambil misi'})))return;
  startNewWorld(c.missions,c.missions.length+' misi diambil dari spreadsheet.');saveWorldState();if(OV[id])OV[id].dirty=false;saveOV();renderWorldCtx();setSendLine($('srvStatus'),'✓ '+c.missions.length+' misi diambil dari spreadsheet.','ok')}
 catch(e){setSendLine($('srvStatus'),String(e.message||e),'err')}}

function bindDunia(){
 $('worldBtn').addEventListener('click',openPicker);$('pickWorld').addEventListener('click',openPicker);$('winWorld').addEventListener('click',()=>{$('winModal').classList.remove('show');openPicker()});
 $('wKelas').addEventListener('change',()=>{student.kelas=$('wKelas').value;save();renderStuChip();renderPicker()});
 $('wList').addEventListener('click',e=>{const b=e.target.closest('[data-world]');if(b)pickWorld(b.dataset.world)});
 $('wClose').addEventListener('click',()=>$('worldModal').classList.remove('show'));
 $('worldModal').addEventListener('click',e=>{if(e.target.id==='worldModal'&&!$('wClose').hidden)$('worldModal').classList.remove('show')})}
