function peerName(){const p=String(student.name||'').trim().split(/\s+/);return(p[0]+(p[1]?' '+p[1][0]+'.':'')).slice(0,18)}
function peerUpdate(list){const now=performance.now(),seen=new Set();
 for(const p of list){if(!p||!p.id||p.id===deviceId)continue;seen.add(p.id);let q=PEERS.get(p.id);const x=Math.max(0,Math.min(COLS-1,p.x|0)),z=Math.max(0,Math.min(ROWS-1,p.y|0));
  if(!q){const r=seedRng('teman|'+p.id);q={id:p.id,ox:(r()-.5)*.5,oz:(r()-.5)*.5,rx:x+0,rz:z+0,face:0,phase:0,moving:false,lbl:null};PEERS.set(p.id,q);if(!peerGreeted.has(p.id)){peerGreeted.add(p.id);toast('👋 '+String(p.n||'Teman')+' ada di dunia ini','purple')}}
  q.n=String(p.n||'Teman');q.x=x+q.ox;q.z=z+q.oz;q.s=p.s|0;q.av=peerAv(String(p.av||''));if(p.e&&(+p.ea||0)<7000){q.emote=String(p.e).slice(0,4);q.emoteUntil=now+7000-(+p.ea||0)}
  if(!q.lbl)q.lbl=mkLbl(q.n,'peer')}
 for(const [id,q] of PEERS)if(!seen.has(id)){if(q.lbl)q.lbl.remove();PEERS.delete(id)}renderPeerHud()}
function clearPeers(){for(const q of PEERS.values())if(q.lbl)q.lbl.remove();PEERS.clear();renderPeerHud()}
function drawPeers(t,dt){for(const q of PEERS.values()){const dx=q.x-q.rx,dz=q.z-q.rz,d=Math.hypot(dx,dz);if(d>.04){const st=Math.min(d,(d>4?d*1.5:3.2)*dt);q.rx+=dx/d*st;q.rz+=dz/d*st;q.face=Math.atan2(dx,dz);q.phase+=dt*10;q.moving=true}else{q.rx=q.x;q.rz=q.z;q.moving=false}
 drawAvatar(q.av,q.rx,hAt(q.rx,q.rz),q.rz,q.face,q.phase,q.moving,t+q.rx)}}
function drawPeerShadows(){for(const q of PEERS.values())shadow(q.rx,q.rz,.55,.2,hAt(q.rx,q.rz))}
function placePeerLabels(){const now=performance.now();for(const q of PEERS.values()){if(!q.lbl)continue;const near=Math.hypot(q.rx-rp.x,q.rz-rp.z)<1.6,em=q.emoteUntil>now?q.emote+' ':'';const txt=em+q.n+(q.s?' · '+q.s+'✓':'');if(q.lbl.textContent!==txt)q.lbl.textContent=txt;q.lbl.classList.toggle('near',near);q.lbl.classList.toggle('emote',!!em);place(q.lbl,q.rx,1.62+hAt(q.rx,q.rz),q.rz)}
 if(LBL.you){const em=myEmoteUntil>now;const t=em?'👋 Kamu':'Kamu';if(LBL.you.textContent!==t)LBL.you.textContent=t}}
function renderPeerHud(){const c=$('peerChip'),w=$('waveBtn');if(!c)return;const on=!!peerOn&&isStudent();c.hidden=!on;w.hidden=!on;if(!on)return;const n=PEERS.size;c.textContent='👥 '+n;c.title=n?'Teman di dunia ini: '+[...PEERS.values()].map(q=>q.n).join(', '):'Belum ada teman lain di dunia ini';c.classList.toggle('has',n>0)}
function wave(){myEmote='👋';myEmoteUntil=performance.now()+6000;SFX.talk();peerTick(true);setTimeout(()=>{if(myEmote)peerTick(true)},1500)}
function bindPeers(){setInterval(()=>peerTick(false),1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)peerTick(true)});$('waveBtn').addEventListener('click',wave);$('peerChip').addEventListener('click',()=>toast(PEERS.size?'Teman di dunia ini: '+[...PEERS.values()].map(q=>q.n).join(', '):'Belum ada teman lain di dunia ini. Ajak temanmu memilih dunia yang sama.'))}
