const MAPEL_RX={};for(const [k,list] of Object.entries(MAPEL_KW))MAPEL_RX[k]=list.map(w=>[w,new RegExp('(^|[^a-z0-9])'+w.replace(/[.*+?^${}()|[\]\\\/]/g,'\\$&')+'(?=$|[^a-z0-9])','g'),w.includes(' ')?2.2:1]);
const EN_STOP=/\b(the|and|of|to|is|are|was|were|in|that|it|with|for|this|which|on|as|by|be)\b/g;
function detectSubject(text){const t=' '+String(text||'').toLowerCase().slice(0,120000)+' ',words=(t.match(/[a-z]+/g)||[]).length||1,sc={},hits={};
 for(const [k,list] of Object.entries(MAPEL_RX)){let s=0,d=0;const h=[];for(const [w,rx,wt] of list){rx.lastIndex=0;const n=Math.min(6,(t.match(rx)||[]).length);if(n){s+=n*wt;d++;h.push([w,n])}}sc[k]=s*(1+d/8);hits[k]=h.sort((a,b)=>b[1]-a[1]).map(x=>x[0])}
 const en=(t.match(EN_STOP)||[]).length/words;if(en>.12)sc['Bahasa Inggris']+=en*60;
 const r=Object.entries(sc).sort((a,b)=>b[1]-a[1]),[best,bs]=r[0],second=r[1]?r[1][1]:0;return{subject:bs>0?best:'',score:bs,conf:bs/(bs+second||1),hits:hits[best]||[],english:en>.12}}
function themeForSource(sub,text){const s=String(sub||'').toLowerCase(),t=String(text||'').toLowerCase().slice(0,60000),has=re=>re.test(t);
 if(/kecerdasan|koding|kka/.test(s))return has(/etika|bias|privasi|hak cipta/)&&!has(/robot|sensor|arduino/)?'etika':has(/data|dataset|basis data/)&&!has(/robot/)?'data':'robot';
 if(/informatika/.test(s)){if(has(/jaringan|router|protokol|tcp|wi-?fi|lan\b/))return'jaringan';if(has(/keamanan|siber|enkripsi|malware|phishing|kata sandi/))return'benteng';if(has(/analisis data|visualisasi|dataset|pandas|grafik data/))return'data';if(has(/perangkat keras|prosesor|motherboard|sistem komputer|cpu/))return'mesin';if(has(/hoaks|penelusuran|mesin pencari|literasi digital/))return'fakta';if(has(/algoritma|pengurutan|pencarian biner|struktur data/))return'labirin';if(has(/python|pemrograman|kode program|\bc\+\+/))return'kode';if(has(/spreadsheet|pengolah kata|presentasi|aplikasi perkantoran/))return'kantor';return'cyber'}
 if(/matematika/.test(s))return'math';if(/fisika/.test(s))return has(/planet|tata surya|bintang|galaksi|orbit|astronomi/)?'antariksa':'science';if(/kimia/.test(s))return'science';if(/biologi/.test(s))return has(/rawa|perairan|ikan|plankton|mangrove/)?'rawa':'forest';
 if(/sejarah/.test(s))return'history';if(/geografi/.test(s))return'pulau';if(/ekonomi|kewirausahaan|prakarya/.test(s))return'pasar';if(/sosiologi/.test(s))return'desa';if(/pancasila|ppkn|kewarganegaraan/.test(s))return'etika';if(/bahasa/.test(s))return'language';if(/agama|islam/.test(s))return'desa';if(/seni/.test(s))return'studio';if(/pjok|olahraga/.test(s))return'pulau';return autoTheme(sub)}
const TOPIC_SKIP=/^(nama|kelas|semester|tahun|sekolah|mata pelajaran|mapel|guru|penyusun|alokasi|kompetensi|tujuan|capaian|modul|halaman|page|url source|published|markdown content|daftar isi|kata pengantar|identitas|fase|jenjang|kurikulum|\[sumber|copyright|hak cipta|isbn)/i;
function detectTopic(label,text){const lines=String(text||'').split(/\n/).map(x=>x.replace(/^[#>*\-\s]+/,'').replace(/\*\*/g,'').trim()).filter(Boolean);
 for(const l of lines.slice(0,60)){let m=l.match(/^title:\s*(.+)/i)||l.match(/^(?:bab|materi|topik|judul|chapter|unit)\s*[:\-–]?\s*(?:[0-9IVXLC]+\b)?\s*[:.\-–]?\s*(.{4,80})$/i);if(m&&!TOPIC_SKIP.test(m[1]))return niceTitle(m[1])}
 for(const l of lines.slice(0,40)){const w=l.split(/\s+/).length;if(l.length<6||l.length>80||w<2||w>11||TOPIC_SKIP.test(l)||/[.:;?]$/.test(l)&&w>6||/^\d|https?:|@|\|/.test(l))continue;if((l.match(/[A-Za-zÀ-ÿ]/g)||[]).length<l.length*.6)continue;return niceTitle(l)}
 return niceTitle(String(label||'').replace(/\.[a-z0-9]{2,5}$/i,'').replace(/[_-]+/g,' '))}
function niceTitle(s){s=String(s||'').replace(/\s*[-|–]\s*(wikipedia|youtube|blogspot|kompas|detik).*$/i,'').replace(/\s+/g,' ').trim().slice(0,70);if(s&&s===s.toUpperCase())s=s.toLowerCase().replace(/(^|\s)\S/g,c=>c.toUpperCase()).replace(/ (Dan|Di|Ke|Dari|Yang|Untuk|Pada|Dengan|Atau|Dalam|Sebagai) /g,m=>m.toLowerCase());return s}
function detectGrade(text){const t=String(text||'').slice(0,20000);let m=t.match(/kelas\s*(XII|XI|X|12|11|10)\b/i);if(m){const v=m[1].toUpperCase();return'SMA Kelas '+({'10':'X','11':'XI','12':'XII'}[v]||v)}m=t.match(/\bfase\s*([EF])\b/i);if(m)return m[1].toUpperCase()==='E'?'SMA Kelas X':'SMA Kelas XI';return''}
let autoSrcTimer=0;
function autoBuildOn(){const c=$('autoBuild');return!!c&&c.checked}
function autoFromSource(label){if(!autoBuildOn()||mode!=='auto'||isStudent())return;clearTimeout(autoSrcTimer);autoSrcTimer=setTimeout(()=>runAutoWorld(label),350)}
function applySourceDetection(label){const all=$('material').value,parts=all.split(/\n?\[Sumber: [^\]]*\]\n/),last=parts[parts.length-1]||all,d=detectSubject(all),info=[];
 if(d.subject&&d.score>=5&&d.conf>=.55){setField('subject',d.subject);info.push('mapel <b>'+escapeHTML(d.subject)+'</b> (kata kunci: '+escapeHTML(d.hits.slice(0,4).join(', '))+')')}else info.push('mapel tidak terdeteksi dengan yakin, tetap memakai <b>'+escapeHTML($('subject').value||'Informatika')+'</b>');
 const tp=detectTopic(label,last);if(tp){setField('topic',tp);info.push('topik <b>'+escapeHTML(tp)+'</b>')}
 const gr=detectGrade(all);if(gr){ensureGradeOption(gr);setField('grade',gr);info.push('<b>'+gr+'</b>')}
 const el=$('detectInfo');if(el){el.hidden=false;el.innerHTML='🔎 Terdeteksi: '+info.join(' · ')+'.'}return d}
function runAutoWorld(label){if(busy)return;const words=($('material').value.match(/\S+/g)||[]).length;if(words<25){setExtract('Teks yang terbaca baru '+words+' kata. Tambahkan sumber lain agar dunia bisa dibuat.','err');return}applySourceDetection(label);generate();const P=palettes[theme]||palettes.cyber;toast('✦ Dunia '+P.emoji+' '+worldTitle+' dibuat dari '+label,'purple')}
function bindSumber(){const c=$('autoBuild');try{c.checked=localStorage.getItem('eduverse-autobuild')!=='0'}catch(e){}c.addEventListener('change',()=>{try{localStorage.setItem('eduverse-autobuild',c.checked?'1':'0')}catch(e){}})}

