let swipe=null;const orbitPointers=new Map();canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{audio();if(e.pointerType==='touch'){orbitPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(orbitPointers.size>=2){const pts=[...orbitPointers.values()];orbitDrag={x:pts.reduce((a,p)=>a+p.x,0)/pts.length,y:pts.reduce((a,p)=>a+p.y,0)/pts.length};swipe=null;return}}if(e.button===2||(e.button===0&&e.shiftKey)){orbitDrag={x:e.clientX,y:e.clientY};canvas.setPointerCapture?.(e.pointerId);return}swipe={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointermove',e=>{if(orbitPointers.has(e.pointerId)){orbitPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(orbitPointers.size>=2&&orbitDrag){const pts=[...orbitPointers.values()],x=pts.reduce((a,p)=>a+p.x,0)/pts.length,y=pts.reduce((a,p)=>a+p.y,0)/pts.length,dx=x-orbitDrag.x,dy=y-orbitDrag.y;orbitDrag={x,y};cameraYaw-=dx*.008;cameraPitch=Math.max(-.55,Math.min(.82,cameraPitch+dy*.006));return}}if(!orbitDrag)return;const dx=e.clientX-orbitDrag.x,dy=e.clientY-orbitDrag.y;orbitDrag={x:e.clientX,y:e.clientY};cameraYaw-=dx*.008;cameraPitch=Math.max(-.55,Math.min(.82,cameraPitch+dy*.006))});canvas.addEventListener('pointerup',e=>{if(e.pointerType==='touch'){orbitPointers.delete(e.pointerId);if(orbitPointers.size<2)orbitDrag=null;if(!swipe)return}if(orbitDrag){orbitDrag=null;return}if(!swipe)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;swipe=null;if(!canPlay())return;if(Math.max(Math.abs(dx),Math.abs(dy))>28){path=[];pendingTarget=null;tryMove(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up')}else{const r=canvas.getBoundingClientRect();tapAt(e.clientX-r.left,e.clientY-r.top)}});canvas.addEventListener('pointercancel',e=>{orbitPointers.delete(e.pointerId);swipe=null;orbitDrag=null});canvas.addEventListener('wheel',e=>{e.preventDefault();cameraZoom=Math.max(.72,Math.min(1.55,cameraZoom+Math.sign(e.deltaY)*.06))},{passive:false});
