const fsEl=()=>document.fullscreenElement||document.webkitFullscreenElement||null;
function setFullUI(on){stage.classList.toggle('full',on);document.body.classList.toggle('locked',on);$('fullBtn').textContent=on?'✕':'⛶';$('fullBtn').setAttribute('aria-label',on?'Keluar layar penuh':'Layar penuh');if(R3D)resize()}
async function toggleFull(){if(stage.classList.contains('full')||fsEl()){if(fsEl()){try{await (document.exitFullscreen||document.webkitExitFullscreen).call(document)}catch(e){}}setFullUI(false);return}
 setFullUI(true);const el=document.documentElement,req=el.requestFullscreen||el.webkitRequestFullscreen;let ok=false;if(req){try{await req.call(el,{navigationUI:'hide'});ok=true}catch(e){ok=false}}
 if(!ok)toast(/iPhone|iPod/.test(navigator.userAgent)?'iPhone tidak mengizinkan layar penuh untuk halaman web. Putar HP ke samping agar lebih luas.':'Layar penuh perangkat tidak diizinkan di sini, jadi game memenuhi jendela browser.');canvas.focus({preventScroll:true})}
['fullscreenchange','webkitfullscreenchange'].forEach(ev=>document.addEventListener(ev,()=>{if(!fsEl()&&stage.classList.contains('full'))setFullUI(false)}));
