$('deleteMission').addEventListener('click',async()=>{if(missions.length<=1){toast('Minimal satu misi harus tersedia.');return}const i=+$('editMission').value;const t=missions[i].title;if(!(await confirmBox('Hapus misi "'+t+'"?',{ok:'Hapus',danger:true})))return;missions.splice(i,1);completed.splice(i,1);wrongs.splice(i,1);refreshSpots();ensurePlayerFree();snapPlayer();rebuildLabels();renderAll();renderEditorSelect();checkReady();save();toast('Misi "'+t+'" dihapus'+(missions.length<MINM?'. Game butuh minimal '+MINM+' misi.':''))});
